mapper.insert:
INSERT INTO send_history ( template_id, user_id, title, content, purpose, status, total_target_count, success_count, fail_count, estimated_cost, estimated_saving, actual_cost, scheduled_at,
) VALUES ( #{templateId}, #{userId}, #{title}, #{content}, #{purpose}, #{status}, #{totalTargetCount}, #{successCount}, #{failCount}, #{estimatedCost}, #{estimatedSaving}, #{actualCost}, #{scheduledAt},
)

INSERT INTO send_history_routing ( send_history_id, channel_id, priority_order,
) VALUES ( #{sendHistoryId}, #{channelId}, #{priorityOrder},
)

mapper.select:
SELECT c.id AS customer_id, c.phone AS phone, c.email AS email, ch.id AS channel_id, ch.channel_type AS channel_type, ch.cost_per_msg AS cost_per_msg, ch.max_length AS max_length, NVL(ccc.is_consented, 0) AS consented FROM customer c JOIN channel ch ON NVL(ch.is_deleted, 0) = 0 AND NVL(ch.is_active, 0) = 1 LEFT JOIN customer_channel_consent ccc ON ccc.customer_id = c.id AND ccc.channel_id = ch.id AND NVL(ccc.is_deleted, 0) = 0 WHERE NVL(c.is_deleted, 0) = 0 AND NVL(c.is_ad_blocked, 0) = 0 AND c.id IN
#{customerId}
ORDER BY c.id ASC, ch.id ASC

mapper.insert:
INSERT INTO send_target ( send_history_id, customer_id, final_channel_id, status, cost, user_uuid,
) VALUES ( #{sendHistoryId}, #{customerId}, #{finalChannelId}, #{status}, #{cost}, #{userUuid},
)

INSERT INTO send_attempt ( send_target_id, attempt_order, channel_id, is_succeeded, solapi_message_id,
) VALUES ( #{sendTargetId}, #{attemptOrder}, #{channelId}, #{isSucceeded}, #{solapiMessageId},
)

mapper.select:
SELECT COUNT(*)
FROM send_real_recipient_whitelist
WHERE channel_type = #{channelType}
  AND recipient_value = #{recipientValue}
  AND NVL(is_active, 0) = 1
